-- PostgreSQL 16+; quantities and money use NUMERIC, never floating point.
CREATE TYPE user_role AS ENUM ('SALESMAN','ADMIN','PRODUCTION','AUDITOR','OWNER');
CREATE TYPE item_kind AS ENUM ('RAW','PACKAGING','FINISHED');
CREATE TYPE order_status AS ENUM ('SUBMITTED','APPROVED','REJECTED','INVOICED','DISPATCHED');
CREATE TYPE run_status AS ENUM ('DRAFT','POSTED','REVERSED');
CREATE TABLE app_user (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role user_role NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE customer (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, state_code CHAR(2) NOT NULL, gstin VARCHAR(15), salesman_id BIGINT REFERENCES app_user(id));
CREATE TABLE supplier (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, gstin VARCHAR(15));
CREATE TABLE item (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, sku TEXT NOT NULL UNIQUE, name TEXT NOT NULL, kind item_kind NOT NULL, base_unit TEXT NOT NULL CHECK (base_unit IN ('kg','litre','piece','packet')), pack_size_g NUMERIC(12,3), selling_price NUMERIC(16,2), hsn_code TEXT, gst_rate NUMERIC(5,2) CHECK (gst_rate BETWEEN 0 AND 100));
CREATE TABLE unit_conversion (item_id BIGINT NOT NULL REFERENCES item(id), from_unit TEXT NOT NULL, to_unit TEXT NOT NULL, factor NUMERIC(20,8) NOT NULL CHECK(factor > 0), PRIMARY KEY(item_id,from_unit,to_unit));
CREATE TABLE bom (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, finished_item_id BIGINT NOT NULL REFERENCES item(id), version INTEGER NOT NULL, expected_packets NUMERIC(18,3) NOT NULL CHECK(expected_packets > 0), active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(finished_item_id,version));
CREATE TABLE bom_line (bom_id BIGINT NOT NULL REFERENCES bom(id), material_item_id BIGINT NOT NULL REFERENCES item(id), standard_qty NUMERIC(18,4) NOT NULL CHECK(standard_qty >= 0), PRIMARY KEY(bom_id,material_item_id));
CREATE TABLE purchase (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, supplier_id BIGINT REFERENCES supplier(id), document_no TEXT NOT NULL UNIQUE, posted_at TIMESTAMPTZ, created_by BIGINT REFERENCES app_user(id));
CREATE TABLE purchase_line (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, purchase_id BIGINT NOT NULL REFERENCES purchase(id), item_id BIGINT NOT NULL REFERENCES item(id), quantity NUMERIC(18,4) NOT NULL CHECK(quantity > 0), unit_rate NUMERIC(16,4) NOT NULL CHECK(unit_rate >= 0));
CREATE TABLE production_run (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, bom_id BIGINT NOT NULL REFERENCES bom(id), batch_multiplier NUMERIC(18,4) NOT NULL DEFAULT 1 CHECK(batch_multiplier > 0), actual_good_packets NUMERIC(18,3) NOT NULL CHECK(actual_good_packets >= 0), status run_status NOT NULL DEFAULT 'DRAFT', posted_at TIMESTAMPTZ, created_by BIGINT REFERENCES app_user(id));
CREATE TABLE production_consumption (run_id BIGINT NOT NULL REFERENCES production_run(id), material_item_id BIGINT NOT NULL REFERENCES item(id), actual_qty NUMERIC(18,4) NOT NULL CHECK(actual_qty >= 0), damaged_qty NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK(damaged_qty >= 0), PRIMARY KEY(run_id,material_item_id));
CREATE TABLE production_overhead (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, run_id BIGINT NOT NULL REFERENCES production_run(id), category TEXT NOT NULL, amount NUMERIC(16,2) NOT NULL CHECK(amount >= 0));
CREATE TABLE sales_order (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, customer_id BIGINT NOT NULL REFERENCES customer(id), salesman_id BIGINT NOT NULL REFERENCES app_user(id), client_request_id UUID NOT NULL UNIQUE, status order_status NOT NULL DEFAULT 'SUBMITTED', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), approved_by BIGINT REFERENCES app_user(id));
CREATE TABLE sales_order_line (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES sales_order(id), item_id BIGINT NOT NULL REFERENCES item(id), quantity NUMERIC(18,3) NOT NULL CHECK(quantity > 0), unit_price NUMERIC(16,2) NOT NULL CHECK(unit_price >= 0));
CREATE TABLE invoice (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE REFERENCES sales_order(id), invoice_no TEXT NOT NULL UNIQUE, financial_year TEXT NOT NULL, supplier_gstin VARCHAR(15), place_of_supply CHAR(2) NOT NULL, taxable_amount NUMERIC(16,2) NOT NULL, cgst NUMERIC(16,2) NOT NULL DEFAULT 0, sgst NUMERIC(16,2) NOT NULL DEFAULT 0, igst NUMERIC(16,2) NOT NULL DEFAULT 0, issued_at TIMESTAMPTZ NOT NULL DEFAULT now(), cancelled_at TIMESTAMPTZ);
CREATE TABLE dispatch (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, invoice_id BIGINT NOT NULL REFERENCES invoice(id), posted_at TIMESTAMPTZ NOT NULL DEFAULT now(), client_request_id UUID NOT NULL UNIQUE);
CREATE TABLE dispatch_line (dispatch_id BIGINT NOT NULL REFERENCES dispatch(id), item_id BIGINT NOT NULL REFERENCES item(id), quantity NUMERIC(18,3) NOT NULL CHECK(quantity > 0), PRIMARY KEY(dispatch_id,item_id));
CREATE TABLE payment (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, invoice_id BIGINT NOT NULL REFERENCES invoice(id), amount NUMERIC(16,2) NOT NULL CHECK(amount > 0), received_at TIMESTAMPTZ NOT NULL DEFAULT now(), reference TEXT NOT NULL UNIQUE);
CREATE TABLE stock_movement (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, item_id BIGINT NOT NULL REFERENCES item(id), quantity_delta NUMERIC(18,4) NOT NULL CHECK(quantity_delta <> 0), unit_cost NUMERIC(16,4), source_type TEXT NOT NULL CHECK(source_type IN ('OPENING','PURCHASE','PRODUCTION_ISSUE','PRODUCTION_OUTPUT','DISPATCH','ADJUSTMENT','REVERSAL')), source_id BIGINT NOT NULL, source_line_key TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), posted_by BIGINT REFERENCES app_user(id), UNIQUE(source_type,source_id,source_line_key));
CREATE INDEX stock_movement_item_time_idx ON stock_movement(item_id,occurred_at,id);
CREATE VIEW stock_balance AS SELECT item_id, SUM(quantity_delta) AS quantity FROM stock_movement GROUP BY item_id;
CREATE TABLE audit_event (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id BIGINT REFERENCES app_user(id), entity_type TEXT NOT NULL, entity_id BIGINT NOT NULL, action TEXT NOT NULL, before_json JSONB, after_json JSONB, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
-- Posting is implemented by backend services in SERIALIZABLE transactions with row locks
-- or advisory locks per item, stock sufficiency checks, idempotency keys and audit events.
-- The schema alone does not enforce the no-negative-stock invariant.
